<template><Card class="s1-ui s1-compact-list"><header class="ui-header"><div><h2>微信支付配置</h2><p>普通微信基础与收付通独立维护。配置管理不执行资金。</p></div><Button type="primary" :disabled="blocked" @click="show=true">新增收付通配置</Button></header><DatasetSwitch :available="demoAvailable" :all="showTestData" @change="switchDataset"/><PageStatus v-bind="$data" :target="pendingTarget" @recover="recover()" @retry="recover(true)" @abandon="abandon"/><DetailSection title="原生普通微信配置摘要" :grid="false"><p v-if="!ordinary" class="ui-note">{{loading?'读取中…':'摘要未读取；不能推定为未配置。'}}</p><template v-else><Alert show-icon>普通微信沿用原维护职责；收付通配置不改变它，也不会自动回退使用它。此摘要不代表真实核验。</Alert><div class="ui-grid"><FieldRow label="配置状态" :value="status(ordinary.state)"/><FieldRow label="更新时间" :value="date(ordinary.updatedAt)"/><FieldRow label="普通商户号" :value="ordinary.mchIdMasked"/><FieldRow label="小程序AppID" :value="ordinary.mpAppIdMasked"/><FieldRow label="公众号AppID" :value="ordinary.jsapiAppIdMasked"/><FieldRow label="Native AppID" :value="ordinary.nativeAppIdMasked"/><FieldRow label="H5 AppID" :value="ordinary.h5AppIdMasked"/><FieldRow label="APP AppID" :value="ordinary.appAppIdMasked"/><FieldRow label="API v3密钥" :value="ordinary.apiKey3Configured===true?'已配置':'未提供'"/><FieldRow label="商户私钥" :value="ordinary.apiclientKeyConfigured===true?'已配置':'未提供'"/><FieldRow label="公钥" :value="ordinary.publicKeyConfigured===true?'已配置':'未提供'"/><FieldRow label="证书序列" :value="ordinary.serialNumberConfigured===true?'已配置':'未提供'"/></div></template></DetailSection><DetailSection title="收付通专属配置" :grid="false"><Alert show-icon>当前环境：{{status(environment)}}／{{status(mode)}}。真实渠道出站：{{realOutbound===true?'已授权':'未授权'}}。</Alert><div class="ui-toolbar"><span>共 {{total}} 条当前环境配置</span><div class="ui-actions"><Button @click="page=1;reload()">回首页刷新</Button><Button @click="reload">刷新当前页</Button></div></div><Table class="s1-list-table" v-compact-table :data="records" :columns="columns" :loading="loading" no-data-text="暂无收付通专属配置"><template slot="mode" slot-scope="{row}"><Tag :color="row.mode==='MOCK'?'orange':'blue'">{{status(row.mode)}}</Tag><span class="ui-meta">{{status(row.environment)}}</span></template><template slot="state" slot-scope="{row}"><Tag :color="row.enabled?'green':'default'">{{row.enabled?'启用':'停用'}}</Tag><span class="ui-meta">{{status(row.checkState)}}</span></template><template slot="operations" slot-scope="{row}"><Button size="small" @click="detail(row.id)">配置详情</Button></template></Table><Page class="ui-pagination" :total="total" :current="page" :page-size="size" show-total @on-change="page=$event;reload()"/></DetailSection><ChannelConfigForm :visible="show" :disabled="blocked" :busy="busy" :error="error" @dirty="dirty=true" @save="save" @cancel="cancel"/></Card></template>
<script>import page from './page';import demo from './demo-data.cjs';import PageStatus from './components/PageStatus';import DetailSection from './components/DetailSection';import FieldRow from './components/FieldRow';import ChannelConfigForm from './components/ChannelConfigForm';import {stage1Confirm} from '../confirm';export default {mixins:[page],components:{PageStatus,DetailSection,FieldRow,ChannelConfigForm},data:()=>({show:false,ordinary:null,environment:null,mode:null,realOutbound:null,columns:[{title:'配置名称',key:'name',minWidth:190},{title:'环境／模式',slot:'mode',minWidth:150},{title:'平台商户号（掩码）',key:'providerMchidMasked',minWidth:180},{title:'支付AppID（掩码）',key:'paymentAppIdMasked',minWidth:190},{title:'启停／检查',slot:'state',minWidth:150},{title:'操作',slot:'operations',width:130}]}),mounted(){this.reload();},methods:{reload(){return this.latest(()=>this.demoActive?this.completeList('/channel-configs').then(v=>{const rows=v.records.filter(r=>!demo.testName(r.name));return {...v,total:rows.length,records:rows.slice((this.page-1)*this.size,this.page*this.size)};}):this.read('/channel-configs',{pageNumber:this.page,pageSize:this.size}),v=>{this.records=v.records;this.total=v.total;this.ordinary=v.ordinaryWechat;this.environment=v.environment;this.mode=v.authorizedMode;this.realOutbound=v.realOutboundAuthorized;},()=>{this.records=[];this.ordinary=null;this.environment=null;this.mode=null;this.realOutbound=null;});},async save(body){try{const result=await this.run('/channel-configs',body);if(result){this.dirty=false;this.show=false;await this.reload();this.detail(result.id);}}catch(_){}},cancel(){if(this.dirty)stage1Confirm({title:'放弃未保存配置？',content:'关闭不会保存或切换配置。',onOk:()=>{this.show=false;this.dirty=false;}});else this.show=false;}}};</script>
